export const analyticsAdministrationSections = [
  { key: 'metrics', title: 'Метрики', description: 'Каталог показників, їхні формули та фільтри.' },
  { key: 'kpis', title: 'KPI з метрик', description: 'Складені показники, ваги й нормалізація.' },
  { key: 'policies', title: 'Правила KPI', description: 'Версії правил розрахунку та перевірка результатів.' },
  { key: 'weight_sets', title: 'Набори ваг', description: 'Набори коефіцієнтів для розрахунку показників.' },
  { key: 'weights', title: 'Ваги цілей', description: 'Коефіцієнти категорій цілей та їхня участь у підсумках.' },
  { key: 'comparison', title: 'Налаштування порівняння', description: 'Набори показників і права доступу для сторінки «Порівняння».' },
  { key: 'users', title: 'Користувачі', description: 'Ролі, дозволені функції та доступ до даних підрозділів.' },
  { key: 'roles', title: 'Ролі та права', description: 'Спільні набори дозволів для користувачів.' },
  { key: 'cache', title: 'Кеш', description: 'Стан кешування, прогрів та очищення результатів.' },
] as const
export type AnalyticsAdministrationSectionId = typeof analyticsAdministrationSections[number]['key']
type Shared = { catalog?: AnalyticsCatalog; weightSets?: BiWeightSet[]; metadata: AnalyticsMetadata; hierarchy: AnalyticsHierarchy; users: BiUsers; token?: string; onSaved: () => Promise<void>; onDirty: (value: boolean) => void }
const versioned = (): BiVersioned => ({ id: crypto.randomUUID().replaceAll('-', ''), revision: 0 })
const clone = <T,>(value: T): T => structuredClone(value)
const pretty = (value: unknown) => JSON.stringify(value, null, 2)
const message = (reason: unknown) => reason instanceof Error ? reason.message : String(reason)
const fieldNames = (metadata: AnalyticsMetadata) => metadata.filter_fields.map(item => typeof item === 'string' ? item : item.field ?? item.key ?? '')
const permissionList = (shared: Pick<Shared, 'metadata'> & Partial<Pick<Shared, 'users'>>) => shared.users?.permissions.length ? shared.users.permissions : (shared.metadata.permission_registry as string[] | undefined) ?? shared.metadata.permissions ?? []
const definitionTitle = (value: BiVersioned & { title?: string; name?: string; category?: string }) => value.title ?? value.name ?? value.category ?? value.id
const defaultMetric = (): BiMetric => ({ ...versioned(), key: '', title: '', description: '', source: 'flights', aggregation: 'COUNT_DISTINCT', field: 'flight_id', filters: [], formula: null, numerator: null, denominator: null, format: { type: 'number', decimals: 0, suffix: '' }, direction: 'NEUTRAL', percentage_difference: 'relative_percent', permissions: [], is_active: true })
const defaultKpi = (): BiKpi => ({ ...versioned(), key: '', title: '', description: '', metrics: [], weights: {}, formula: { value: 0 }, normalization: 'NONE', normalization_metric: null, minimum: null, maximum: null, format: { type: 'number', decimals: 2, suffix: '' }, direction: 'HIGHER_IS_BETTER', permissions: [], is_active: true })
const defaultComparisonDefinition = (): DashboardDefinition => ({ ...versioned(), name: 'Новий набір порівняння', slug: `comparison_${Date.now()}`, description: '', type: 'COMPARISON', is_system: true, layout_mode: 'LOCKED', version: 2, widgets: [], assignments: [], global_filters: [] })
const defaultWeight = (): BiWeight => ({ ...versioned(), weight_set_id: 'target_equivalent', category: '', weight: 1, include_in_general_total: true, display_separately: false, include_in_weighted_total: true, excluded_from_general_total: false })
const defaultRole = (): BiRole => ({ ...versioned(), key: '', title: '', permissions: [] })

function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="bia-field"><span>{label}</span>{children}</label> }
function Check({ label, value, onChange }: { label: string; value: boolean; onChange: (value: boolean) => void }) { return <label className="bia-check"><input type="checkbox" checked={value} onChange={event => onChange(event.target.checked)} />{label}</label> }
function Choices({ title, options, selected, onChange }: { title: string; options: Array<{ key: string; title: string }>; selected: string[]; onChange: (value: string[]) => void }) {
  const [search, setSearch] = useState('')
  return <fieldset className="bia-choices"><legend>{title}</legend>{options.length > 10 && <input aria-label={`Пошук: ${title}`} placeholder="Пошук…" value={search} onChange={event => setSearch(event.target.value)} />}<div>{options.filter(option => `${option.key} ${option.title}`.toLowerCase().includes(search.toLowerCase())).map(option => <Check key={option.key} label={option.title} value={selected.includes(option.key)} onChange={value => onChange(value ? [...selected, option.key] : selected.filter(key => key !== option.key))} />)}</div>{!options.length && <p className="bi-notice">Немає доступних значень.</p>}</fieldset>
}
function JsonEditor<T>({ label, value, onChange, onError }: { label: string; value: T; onChange: (value: T) => void; onError?: (error: string) => void }) {
  const serialized = pretty(value)
  const [raw, setRaw] = useState(serialized)
  const [error, setError] = useState('')
  useEffect(() => { setRaw(serialized); setError(''); onError?.('') }, [serialized])
  return <Field label={label}><textarea className="bia-json" value={raw} aria-invalid={Boolean(error)} onChange={event => { setRaw(event.target.value); try { const parsed = JSON.parse(event.target.value) as T; onChange(parsed); setError(''); onError?.('') } catch { const next = 'Некоректний JSON. Виправте перед збереженням.'; setError(next); onError?.(next) } }} />{error && <small role="alert" className="bia-error">{error}</small>}</Field>
}
function FiltersEditor({ title, filters, metadata, onChange, onError }: { title: string; filters: QueryFilter[]; metadata: AnalyticsMetadata; onChange: (value: QueryFilter[]) => void; onError: (error: string) => void }) {
  const fields = fieldNames(metadata)
  const operators = (metadata.filter_operators as string[] | undefined) ?? metadata.operators ?? ['eq', 'neq', 'in', 'not_in', 'gt', 'gte', 'lt', 'lte', 'contains', 'not_contains', 'is_null', 'is_not_null', 'between']
  const change = (index: number, update: Partial<QueryFilter>) => onChange(filters.map((filter, current) => current === index ? { ...filter, ...update } : filter))
  return <div className="bia-filter-editor"><h4>{title}</h4>{filters.map((filter, index) => <div className="bia-filter-row" key={index}><select aria-label={`${title}: поле ${index + 1}`} value={filter.field} onChange={event => change(index, { field: event.target.value })}>{fields.map(field => <option value={field} key={field}>{field}</option>)}</select><select aria-label={`${title}: оператор ${index + 1}`} value={filter.operator} onChange={event => { const operator = event.target.value; change(index, { operator, value: ['in', 'not_in', 'between'].includes(operator) ? [] : operator.includes('null') ? null : '' }); onError('') }}>{operators.map(operator => <option value={operator} key={operator}>{operator}</option>)}</select>{!filter.operator.includes('null') && <FilterValue key={`${index}:${filter.operator}`} filter={filter} onChange={value => change(index, { value })} onError={onError} label={`${title}: значення ${index + 1}`} />}<button className="secondary" type="button" aria-label={`Видалити фільтр ${index + 1}`} onClick={() => { onChange(filters.filter((_, current) => current !== index)); onError('') }}><Trash2 size={13} /></button></div>)}<button className="secondary" type="button" onClick={() => onChange([...filters, { field: fields[0] ?? 'category', operator: 'eq', value: '' }])}><Plus size={13} /> Додати фільтр</button><p className="bi-notice">Для in / not_in / between: список через кому або JSON-масив. Усі фільтри об’єднуються через AND.</p></div>
}
function FilterValue({ filter, onChange, onError, label }: { filter: QueryFilter; onChange: (value: unknown) => void; onError: (error: string) => void; label: string }) {
  const serialized = typeof filter.value === 'string' ? filter.value : JSON.stringify(filter.value ?? '')
  const [raw, setRaw] = useState(serialized)
  useEffect(() => setRaw(serialized), [serialized])
  return <input aria-label={label} value={raw} onChange={event => { setRaw(event.target.value); try { onChange(parseFilterInput(event.target.value, filter.operator)); onError('') } catch (reason) { onError(message(reason)) } }} />
}
function Formatting({ format, onChange }: { format: MetricFormat; onChange: (value: MetricFormat) => void }) {
  return <div className="bia-fields"><Field label="Формат"><select value={format.type ?? 'number'} onChange={event => onChange({ ...format, type: event.target.value })}>{['number', 'percent', 'currency', 'duration'].map(type => <option key={type}>{type}</option>)}</select></Field><Field label="Знаків після коми"><input type="number" min={0} max={8} value={format.decimals ?? 0} onChange={event => onChange({ ...format, decimals: Number(event.target.value) })} /></Field><Field label="Суфікс / одиниця"><input value={format.suffix ?? ''} maxLength={40} onChange={event => onChange({ ...format, suffix: event.target.value })} /></Field></div>
}
function DateFields({ range, onChange }: { range: { from: string; to: string }; onChange: (value: { from: string; to: string }) => void }) { return <div className="bia-fields"><Field label="Від"><input type="date" value={range.from} onChange={event => onChange({ ...range, from: event.target.value })} /></Field><Field label="До"><input type="date" value={range.to} onChange={event => onChange({ ...range, to: event.target.value })} /></Field></div> }
function initialRange() { const today = new Date(); const end = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`; return { from: `${end.slice(0, 7)}-01`, to: end } }

function DefinitionEditor<T extends BiVersioned>({ entity, items, create, shared, render }: { entity: BiEntity; items: T[]; create: () => T; shared: Shared; render: (draft: T, setDraft: (value: T) => void, invalid: (name: string, error: string) => void) => ReactNode }) {
  const [draft, setDraft] = useState<T>(() => clone(items[0] ?? create()))
  const [base, setBase] = useState(() => pretty(items[0] ?? draft))
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [invalid, setInvalid] = useState<Record<string, string>>({})
  const dirty = pretty(draft) !== base
  useEffect(() => { shared.onDirty(dirty); return () => shared.onDirty(false) }, [dirty])
  useEffect(() => {
    if (dirty || busy) return
    const latest = items.find(item => item.id === draft.id)
    if (!latest || latest.revision < draft.revision || pretty(latest) === base) return
    setDraft(clone(latest)); setBase(pretty(latest)); setError(''); setInvalid({})
  }, [items, draft.id, draft.revision, base, dirty, busy])
  const load = (value: T) => { setDraft(clone(value)); setBase(pretty(value)); setError(''); setNotice(''); setInvalid({}) }
  const perform = async (action: 'save' | 'delete') => {
    if (Object.values(invalid).some(Boolean)) { setError('Виправте помилки у формі.'); return }
    setBusy(true); setError(''); setNotice('')
    try {
      if (action === 'save') { const saved = await biAdminApi.save(entity, draft, shared.token); load(saved); setNotice('Збережено. Зміни застосовано до спільних налаштувань.') }
      else { await biAdminApi.remove(entity, draft, shared.token); load(create()); setNotice('Видалено.') }
      await shared.onSaved()
    } catch (reason) { setError(message(reason)) }
    finally { setBusy(false) }
  }
  return <div className="bia-definition"><div className="bia-list"><button type="button" className="secondary" disabled={busy || dirty} onClick={() => load(create())}><Plus size={14} /> Створити</button>{items.map(item => <button type="button" disabled={busy || dirty} key={item.id} className={item.id === draft.id ? 'active' : ''} onClick={() => load(item)}>{definitionTitle(item)}<small>v{item.revision}</small></button>)}</div><div className="bia-editor"><fieldset disabled={busy} className="bia-form">{render(draft, setDraft, (name, next) => setInvalid(current => current[name] === next ? current : { ...current, [name]: next }))}</fieldset>{error && <div className="bi-error-banner" role="alert">{error}</div>}{notice && <p className="bi-notice" role="status">{notice}</p>}<div className="bia-actions"><button type="button" className="secondary" disabled={busy || Object.values(invalid).some(Boolean)} onClick={() => void perform('save')}><Save size={14} /> {busy ? 'Збереження…' : 'Зберегти'}</button>{draft.revision > 0 && <button type="button" className="secondary" disabled={busy || dirty} onClick={() => void perform('delete')}><Trash2 size={14} /> Видалити</button>}{dirty && <button type="button" className="secondary" disabled={busy} onClick={() => load(JSON.parse(base) as T)}><X size={14} /> Скасувати</button>}</div>{dirty && <p className="bi-notice">Є незбережені зміни. Збережіть або скасуйте їх, щоб перейти до іншого визначення.</p>}</div></div>
}

function QueryPreview({ query, shared, entity, definition }: { query: QueryRequest; shared: Shared; entity?: 'metrics' | 'kpis'; definition?: BiMetric | BiKpi }) {
  const [range, setRange] = useState(initialRange)
  const [result, setResult] = useState<QueryResult>()
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const preview = async () => { setLoading(true); setError(''); try { setResult(entity && definition ? await biAdminApi.previewDefinition(entity, definition, { ...query, date_range: range }, shared.token) : await biAdminApi.query({ ...query, date_range: range }, shared.token)) } catch (reason) { setError(message(reason)) } finally { setLoading(false) } }
  useEffect(() => { setResult(undefined); setError('') }, [pretty(query), definition && pretty(definition)])
  const widget: WidgetDefinition = { id: 'preview', title: 'Попередній перегляд', widget_type: 'chart', layout: { x: 0, y: 0, w: 12, h: 4 }, query, visualization: { type: query.dimensions.length ? 'bar' : 'number' } }
  return <details className="bia-advanced"><summary>Попередній перегляд розрахунку</summary><DateFields range={range} onChange={setRange} /><button type="button" className="secondary" disabled={loading || !query.metrics.length} onClick={() => void preview()}><Eye size={14} /> Розрахувати на джерелі</button><div className="bia-preview"><WidgetRenderer definition={widget} result={result} loading={loading} error={error} /></div></details>
}

function MetricEditor({ items, shared }: { items: BiMetric[]; shared: Shared }) {
  const fields = fieldNames(shared.metadata)
  const sources = (shared.metadata.sources ?? []).map(item => typeof item === 'string' ? item : String(item.key ?? item.source ?? ''))
  return <DefinitionEditor entity="metrics" items={items} create={defaultMetric} shared={shared} render={(draft, setDraft, invalid) => <><h3>Показник каталогу</h3><Field label="Назва показника"><input value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} /></Field><Field label="Опис"><textarea value={draft.description ?? ''} onChange={event => setDraft({ ...draft, description: event.target.value })} /></Field><details className="bia-advanced"><summary>Advanced: джерело та обчислення метрики</summary><h3>Визначення метрики</h3><div className="bia-fields"><Field label="Ключ"><input value={draft.key} pattern="[a-zA-Z][a-zA-Z0-9_]*" onChange={event => setDraft({ ...draft, key: event.target.value })} /></Field><Field label="Назва"><input value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} /></Field></div><Field label="Опис"><textarea value={draft.description ?? ''} onChange={event => setDraft({ ...draft, description: event.target.value })} /></Field><div className="bia-fields"><Field label="Джерело"><select value={draft.source} onChange={event => setDraft({ ...draft, source: event.target.value })}>{sources.map(source => <option key={source}>{source}</option>)}</select></Field><Field label="Агрегація"><select value={draft.aggregation} onChange={event => setDraft({ ...draft, aggregation: event.target.value, ...(event.target.value === 'FORMULA' && !draft.formula ? { formula: { value: 0 } } : {}) })}>{shared.metadata.aggregations.map(item => <option key={item}>{item}</option>)}</select></Field>{!['COUNT', 'RATIO', 'FORMULA'].includes(draft.aggregation) && <Field label="Поле"><select value={draft.field ?? ''} onChange={event => setDraft({ ...draft, field: event.target.value })}><option value="">Оберіть поле</option>{fields.map(field => <option key={field}>{field}</option>)}</select></Field>}</div>{draft.aggregation === 'WEIGHTED_SUM' && <Field label="Поле категорії для ваг"><select value={draft.category_field ?? 'category'} onChange={event => setDraft({ ...draft, category_field: event.target.value })}>{fields.map(field => <option key={field}>{field}</option>)}</select></Field>}{draft.aggregation === 'RATIO' && <div className="bia-fields">{(['numerator', 'denominator'] as const).map(key => <Field key={key} label={key === 'numerator' ? 'Метрика чисельника' : 'Метрика знаменника'}><select value={draft[key] ?? ''} onChange={event => setDraft({ ...draft, [key]: event.target.value })}><option value="">Оберіть метрику</option>{shared.metadata.metrics.filter(metric => metric.key !== draft.key).map(metric => <option key={metric.key} value={metric.key}>{metric.title}</option>)}</select></Field>)}</div>}{draft.aggregation === 'FORMULA' && <><p className="bi-notice">Безпечне дерево: {`{"op":"add","args":[{"metric":"metric_a"},{"metric":"metric_b"}]}`}.</p><JsonEditor label="Формула (JSON AST)" value={draft.formula} onChange={formula => setDraft({ ...draft, formula })} onError={error => invalid('formula', error)} /></>}<FiltersEditor title="Фільтри метрики" filters={draft.filters ?? []} metadata={shared.metadata} onChange={filters => setDraft({ ...draft, filters })} onError={error => invalid('filters', error)} /><Field label="Набір ваг"><select value={String(draft.weight_set_id ?? 'target_equivalent')} onChange={event => setDraft({ ...draft, weight_set_id: event.target.value })}>{shared.weightSets?.map(set => <option key={set.id} value={set.id}>{set.title}</option>)}</select></Field><Field label="Категорії у результаті"><select value={String(draft.category_mode ?? 'ALL')} onChange={event => setDraft({ ...draft, category_mode: event.target.value })}><option value="ALL">Усі категорії</option><option value="GENERAL">Загальний результат</option><option value="SEPARATE">Окремі спеціальні категорії</option></select></Field><Formatting format={draft.format ?? {}} onChange={format => setDraft({ ...draft, format })} /><div className="bia-fields"><Field label="Напрям"><select value={draft.direction ?? 'NEUTRAL'} onChange={event => setDraft({ ...draft, direction: event.target.value })}>{['HIGHER_IS_BETTER', 'LOWER_IS_BETTER', 'NEUTRAL'].map(value => <option key={value}>{value}</option>)}</select></Field><Field label="Різниця процентної метрики"><select value={draft.percentage_difference ?? 'relative_percent'} onChange={event => setDraft({ ...draft, percentage_difference: event.target.value })}><option value="relative_percent">Відносні відсотки</option><option value="percentage_points">Відсоткові пункти</option></select></Field></div><Check label="Метрика активна" value={draft.is_active !== false} onChange={is_active => setDraft({ ...draft, is_active })} /><details className="bia-advanced"><summary>Права доступу до метрики</summary><Choices title="Потрібні права" options={permissionList(shared).map(key => ({ key, title: key }))} selected={draft.permissions ?? []} onChange={permissions => setDraft({ ...draft, permissions })} /></details><QueryPreview query={{ metrics: draft.key ? [{ key: draft.key }] : [], dimensions: [], filters: [] }} entity="metrics" definition={draft} shared={shared} /></details></>} />
}

function KpiEditor({ items, shared }: { items: BiKpi[]; shared: Shared }) {
  return <DefinitionEditor entity="kpis" items={items} create={defaultKpi} shared={shared} render={(draft, setDraft, invalid) => <><h3>KPI із кількох метрик</h3><div className="bia-fields"><Field label="Ключ KPI"><input value={draft.key} onChange={event => setDraft({ ...draft, key: event.target.value })} /></Field><Field label="Назва KPI"><input value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} /></Field></div><Field label="Опис"><textarea value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} /></Field><Choices title="Метрики KPI" options={shared.metadata.metrics.filter(metric => metric.key !== draft.key).map(metric => ({ key: metric.key, title: metric.title }))} selected={draft.metrics.map(metric => metric.key)} onChange={keys => setDraft({ ...draft, metrics: keys.map(key => ({ key })) })} />{draft.metrics.map(metric => <Field key={metric.key} label={`Вага: ${shared.metadata.metrics.find(item => item.key === metric.key)?.title ?? metric.key}`}><input type="number" step="any" value={draft.weights[metric.key] ?? 1} onChange={event => setDraft({ ...draft, weights: { ...draft.weights, [metric.key]: Number(event.target.value) } })} /></Field>)}<button type="button" className="secondary" disabled={!draft.metrics.length} onClick={() => setDraft({ ...draft, formula: buildWeightedFormula(draft.metrics, draft.weights) })}>Побудувати формулу з ваг</button><JsonEditor label="Формула KPI (JSON AST)" value={draft.formula} onChange={formula => setDraft({ ...draft, formula })} onError={error => invalid('formula', error)} /><div className="bia-fields"><Field label="Нормалізація"><select value={draft.normalization} onChange={event => setDraft({ ...draft, normalization: event.target.value })}>{['NONE', 'PER_OPERATION', 'PER_100_OPERATIONS', 'PERCENT_OF_TOTAL', 'RATIO', 'MIN_MAX'].map(value => <option key={value}>{value}</option>)}</select></Field>{!['NONE', 'MIN_MAX'].includes(draft.normalization) && <Field label="Метрика знаменника"><select value={draft.normalization_metric ?? ''} onChange={event => setDraft({ ...draft, normalization_metric: event.target.value })}><option value="">Оберіть метрику</option>{shared.metadata.metrics.filter(metric => metric.key !== draft.key).map(metric => <option value={metric.key} key={metric.key}>{metric.title}</option>)}</select></Field>}{['minimum', 'maximum'].map(key => <Field label={key === 'minimum' ? 'Мінімум' : 'Максимум'} key={key}><input type="number" step="any" value={draft[key as 'minimum' | 'maximum'] ?? ''} onChange={event => setDraft({ ...draft, [key]: event.target.value === '' ? null : Number(event.target.value) })} /></Field>)}</div><Formatting format={draft.format} onChange={format => setDraft({ ...draft, format })} /><Field label="Напрям KPI"><select value={draft.direction} onChange={event => setDraft({ ...draft, direction: event.target.value })}>{['HIGHER_IS_BETTER', 'LOWER_IS_BETTER', 'NEUTRAL'].map(value => <option key={value}>{value}</option>)}</select></Field><Check label="KPI активний" value={draft.is_active} onChange={is_active => setDraft({ ...draft, is_active })} /><details className="bia-advanced"><summary>Права доступу до KPI</summary><Choices title="Потрібні права" options={permissionList(shared).map(key => ({ key, title: key }))} selected={draft.permissions} onChange={permissions => setDraft({ ...draft, permissions })} /></details><QueryPreview query={{ metrics: draft.key ? [{ key: draft.key }] : [], dimensions: [] }} entity="kpis" definition={draft} shared={shared} /></>} />
}

function ComparisonPresetsEditor({ items, shared }: { items: DashboardDefinition[]; shared: Shared }) {
  const [draft, setDraft] = useState(() => clone(items[0] ?? defaultComparisonDefinition()))
  const [base, setBase] = useState(() => pretty(items[0] ?? draft))
  const [editingWidget, setEditingWidget] = useState<WidgetDefinition | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [range, setRange] = useState(initialRange)
  const [preview, setPreview] = useState<Record<string, { data?: QueryResult; error?: string }>>({})
  const filterOptions = useQuery({ queryKey: ['bi-admin', 'comparison-options', range], queryFn: ({ signal }) => biAdminApi.catalogOptions(range, shared.token, signal), enabled: Boolean(shared.catalog), retry: false })
  const semanticCatalog = shared.catalog ? { ...shared.catalog, filters: shared.catalog.filters.map(field => ({ ...field, values: filterOptions.data?.[field.key] ?? filterOptions.data?.[semanticField(field)] ?? field.values })) } : undefined
  const dirty = pretty(draft) !== base
  useEffect(() => { shared.onDirty(dirty || Boolean(editingWidget)); return () => shared.onDirty(false) }, [dirty, editingWidget])
  useEffect(() => {
    if (dirty || busy || editingWidget) return
    const latest = items.find(item => item.id === draft.id)
    if (!latest || latest.revision < draft.revision || pretty(latest) === base) return
    setDraft(clone(latest)); setBase(pretty(latest)); setError(''); setPreview({})
  }, [items, draft.id, draft.revision, base, dirty, busy, editingWidget])
  const load = (dashboard: DashboardDefinition) => { setDraft(clone(dashboard)); setBase(pretty(dashboard)); setError(''); setNotice(''); setPreview({}) }
  const changeWidgets = (widgets: WidgetDefinition[]) => { setDraft({ ...draft, widgets }); setPreview({}) }
  const addWidget = () => {
    setEditingWidget({ ...versioned(), dashboard_id: draft.id, title: 'Новий набір показників', widget_type: 'chart', layout: nextWidgetLayout(draft.widgets), query: { metrics: shared.metadata.metrics.slice(0, 2).map(metric => ({ key: metric.key })), dimensions: [], filters: [], sort: [], top_n: null, date_range: null }, visualization: { type: 'number', series: [], axes: {}, legend: {}, labels: {}, tooltip: {}, options: {} }, permissions: { required_permissions: [], roles: [], users: [] }, data_scope: 'USER_SCOPE', fixed_filters: [], inherit_global_filters: true, date_mode: 'INHERIT_GLOBAL_DATE', is_locked: false })
  }
  const save = async () => { setBusy(true); setError(''); setNotice(''); try { const saved = await biAdminApi.save('dashboards', draft, shared.token); load(saved); await shared.onSaved(); setNotice('Набір порівняння збережено. Він доступний призначеним користувачам.') } catch (reason) { setError(message(reason)) } finally { setBusy(false) } }
  const remove = async () => { setBusy(true); setError(''); try { await biAdminApi.remove('dashboards', draft, shared.token); load(defaultComparisonDefinition()); await shared.onSaved(); setNotice('Набір порівняння видалено.') } catch (reason) { setError(message(reason)) } finally { setBusy(false) } }
  const runPreview = async () => {
    if (!draft.widgets.length) return
    setBusy(true); setError('')
    try {
      const values = await biAdminApi.batch(draft.widgets.map(widget => ({ ...widget.query, date_range: widget.date_mode === 'USE_FIXED_DATE' ? widget.query.date_range : range, filters: [...(widget.query.filters ?? []), ...(widget.fixed_filters ?? []), ...(widget.inherit_global_filters !== false ? draft.global_filters ?? [] : [])], data_scope: widget.data_scope, ...(widget.data_scope === 'FIXED_SCOPE' ? { fixed_scope: { scope_type: 'CUSTOM', scope_ids: [], filters: widget.fixed_filters ?? [] } } : {}) })), shared.token)
      setPreview(Object.fromEntries(draft.widgets.map((widget, index) => [widget.id, { data: values.results[index]?.data, error: values.results[index]?.error?.message }])))
    } catch (reason) { setError(message(reason)) } finally { setBusy(false) }
  }
  return <div className="bia-definition bia-definition-dashboard"><div className="bia-list"><button className="secondary" type="button" disabled={busy || dirty || Boolean(editingWidget)} onClick={() => load(defaultComparisonDefinition())}><Plus size={14} /> Створити набір порівняння</button>{items.map(item => <button key={item.id} type="button" className={item.id === draft.id ? 'active' : ''} disabled={busy || dirty || Boolean(editingWidget)} onClick={() => load(item)}>{item.name}<small>Версія {item.revision}</small></button>)}</div><div className="bia-editor"><fieldset disabled={busy} className="bia-form"><details open><summary>Назва та призначення набору</summary><div className="bia-fields"><Field label="Назва набору"><input value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} /></Field></div><Field label="Опис"><textarea value={draft.description ?? ''} onChange={event => setDraft({ ...draft, description: event.target.value })} /></Field><h4>Призначення (порожньо — усі з правом перегляду сторінки)</h4>{(draft.assignments ?? []).map((assignment, index) => {
      const type = assignment.assignment_type ?? 'role'
      const choices = type === 'role' ? shared.users.roles.map(role => ({ id: role.id, title: role.title })) : type === 'user' ? shared.users.users.map(user => ({ id: user.id, title: user.display_name || user.username })) : type === 'department' ? shared.hierarchy.departments : shared.hierarchy.groups
      return <div className="bia-filter-row" key={index}><select aria-label={`Тип призначення ${index + 1}`} value={type} onChange={event => setDraft({ ...draft, assignments: draft.assignments?.map((value, current) => current === index ? { assignment_type: event.target.value, assignment_id: '' } : value) })}>{[['role', 'Роль'], ['user', 'Користувач'], ['department', 'ББАК'], ['group', 'Рота']].map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><select aria-label={`Отримувач призначення ${index + 1}`} value={String(assignment.assignment_id ?? '')} onChange={event => setDraft({ ...draft, assignments: draft.assignments?.map((value, current) => current === index ? { ...value, assignment_id: event.target.value } : value) })}><option value="">Оберіть отримувача</option>{choices.map(value => <option value={value.id} key={value.id}>{value.title}</option>)}</select><button type="button" className="secondary" onClick={() => setDraft({ ...draft, assignments: draft.assignments?.filter((_, current) => current !== index) })}>Видалити</button></div>
    })}<button type="button" className="secondary" onClick={() => setDraft({ ...draft, assignments: [...(draft.assignments ?? []), { assignment_type: 'role', assignment_id: shared.users.roles[0]?.id ?? '' }] })}>Додати призначення</button>{semanticCatalog && <SemanticFilterControls title="Спільні фільтри набору" filters={draft.global_filters ?? []} catalog={semanticCatalog} onChange={global_filters => setDraft({ ...draft, global_filters })} />}</details><div className="bia-canvas-toolbar"><h3>Набори показників</h3><button type="button" className="secondary" onClick={addWidget}><Plus size={14} /> Додати набір показників</button><button type="button" className="secondary" disabled={!draft.widgets.length} onClick={() => void runPreview()}><Eye size={14} /> Попередній перегляд</button><button type="button" className="secondary" onClick={() => changeWidgets(draft.widgets.map((widget, index) => ({ ...widget, layout: { x: (index % 2) * 6, y: Math.floor(index / 2) * 5, w: 6, h: 5 } })))}>Вирівняти набори</button></div><DateFields range={range} onChange={setRange} /><DashboardGrid widgets={draft.widgets} editable manageWidgets onLayoutsChange={layouts => changeWidgets(draft.widgets.map(widget => layouts[widget.id] ? { ...widget, layout: layouts[widget.id] } : widget))} onEdit={setEditingWidget} onDuplicate={widget => changeWidgets([...draft.widgets, { ...clone(widget), ...versioned(), title: `${widget.title} (копія)`, layout: nextWidgetLayout(draft.widgets) }])} onDelete={widget => changeWidgets(draft.widgets.filter(item => item.id !== widget.id))} renderWidget={widget => <WidgetRenderer definition={widget} result={preview[widget.id]?.data} loading={busy} error={preview[widget.id]?.error} />} />{!draft.widgets.length && <p className="bi-state">Додайте набір показників і перевірте його у попередньому перегляді.</p>}</fieldset>{error && <div className="bi-error-banner" role="alert">{error}</div>}{notice && <p className="bi-notice" role="status">{notice}</p>}<div className="bia-actions"><button type="button" className="secondary" disabled={busy || !draft.name.trim()} onClick={() => void save()}><Save size={14} /> {busy ? 'Збереження…' : 'Зберегти налаштування'}</button>{draft.revision > 0 && <button type="button" className="secondary" disabled={busy || dirty} onClick={() => void remove()}><Trash2 size={14} /> Видалити набір порівняння</button>}{dirty && <button type="button" className="secondary" disabled={busy} onClick={() => load(JSON.parse(base) as DashboardDefinition)}>Скасувати зміни</button>}</div><p className="bi-notice">Збережені набори показників доступні на сторінці порівняння. Дашборд і статистика редагуються на своїх сторінках.</p></div>{editingWidget && semanticCatalog && <SemanticWidgetEditor widget={editingWidget} catalog={{ ...semanticCatalog, metrics: semanticCatalog.metrics.filter(metric => metric.kind !== 'builtin') }} system dateRange={range} globalFilters={draft.global_filters ?? []} previewRequest={body => biAdminApi.previewWidget(body, shared.token)} onClose={() => setEditingWidget(null)} onSave={async widget => { changeWidgets(draft.widgets.some(item => item.id === widget.id) ? draft.widgets.map(item => item.id === widget.id ? widget : item) : [...draft.widgets, widget]); setEditingWidget(null) }} />}</div>
}

function WeightSetEditor({ items, shared }: { items: BiWeightSet[]; shared: Shared }) {
  return <DefinitionEditor entity="weight_sets" items={items} create={() => ({ ...versioned(), key: '', title: '', description: '', is_active: true })} shared={shared} render={(draft, setDraft) => <><h3>Набір ваг</h3><Field label="Назва"><input value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} /></Field><Field label="Опис"><textarea value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} /></Field><Check label="Набір активний" value={draft.is_active} onChange={is_active => setDraft({ ...draft, is_active })} /><details><summary>Advanced: стабільний ключ</summary><Field label="Ключ"><input value={draft.key} onChange={event => setDraft({ ...draft, key: event.target.value })} /></Field></details></>} />
}
function WeightEditor({ items, shared }: { items: BiWeight[]; shared: Shared }) {
  return <DefinitionEditor entity="category_weights" items={items} create={defaultWeight} shared={shared} render={(draft, setDraft) => <><h3>Вага категорії цілі</h3><Field label="Набір ваг"><select value={draft.weight_set_id ?? 'target_equivalent'} onChange={event => setDraft({ ...draft, weight_set_id: event.target.value })}>{shared.weightSets?.map(set => <option key={set.id} value={set.id}>{set.title}</option>)}</select></Field><Field label="Категорія цілі"><input value={draft.category} onChange={event => setDraft({ ...draft, category: event.target.value })} /></Field><Field label="Вага / еквівалент"><input type="number" min={0} max={1000000} step="any" value={draft.weight} onChange={event => setDraft({ ...draft, weight: Number(event.target.value) })} /></Field><Check label="Показувати окремо" value={draft.display_separately} onChange={display_separately => setDraft({ ...draft, display_separately })} /><Check label="Включати до зваженого результату" value={draft.include_in_weighted_total} onChange={include_in_weighted_total => setDraft({ ...draft, include_in_weighted_total })} /><Check label="Включати до загального результату" value={draft.include_in_general_total !== false && !draft.excluded_from_general_total} onChange={include_in_general_total => setDraft({ ...draft, include_in_general_total, excluded_from_general_total: !include_in_general_total })} /><p className="bi-notice">Кількісні метрики залишаються незваженими. Спеціальні категорії можуть мати власний блок і не входити до загального результату.</p></>} />
}
function RoleEditor({ items, shared }: { items: BiRole[]; shared: Shared }) {
  return <DefinitionEditor entity="roles" items={items} create={defaultRole} shared={shared} render={(draft, setDraft) => <><h3>Роль користувача</h3><div className="bia-fields"><Field label="Ключ ролі"><input value={draft.key} onChange={event => setDraft({ ...draft, key: event.target.value })} /></Field><Field label="Назва ролі"><input value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value })} /></Field></div><Choices title="Feature permissions" options={permissionList(shared).map(key => ({ key, title: key }))} selected={draft.permissions} onChange={permissions => setDraft({ ...draft, permissions })} /><p className="bi-notice">Роль задає функції. Область доступних даних призначається користувачу окремо.</p></>} />
}
function UsersEditor({ shared }: { shared: Shared }) {
  const users = shared.users.users
  const createFor = (userId: string): BiUserAccess => clone(shared.users.access.find(item => item.user_id === userId) ?? { ...versioned(), user_id: userId, role_ids: [], permissions: [], denied_permissions: [], data_scope: { scope_type: 'NONE', scope_ids: [], filters: [] }, comparison_precision: 'ROUND_5' })
  const [selected, setSelected] = useState(users[0]?.id ?? '')
  const [draft, setDraft] = useState<BiUserAccess>(() => createFor(selected))
  const [base, setBase] = useState(() => pretty(draft))
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [invalid, setInvalid] = useState('')
  const dirty = pretty(draft) !== base
  useEffect(() => { shared.onDirty(dirty); return () => shared.onDirty(false) }, [dirty])
  useEffect(() => {
    if (dirty || busy) return
    const selectedUser = users.find(item => item.id === selected) ?? users[0]
    if (!selectedUser) return
    const latest = selectedUser.id === selected ? shared.users.access.find(item => item.user_id === selected) : createFor(selectedUser.id)
    if (!latest || (selectedUser.id === selected && (latest.revision < draft.revision || pretty(latest) === base))) return
    setSelected(selectedUser.id); setDraft(clone(latest)); setBase(pretty(latest)); setError(''); setInvalid('')
  }, [shared.users, users, selected, draft.revision, base, dirty, busy])
  const user = users.find(item => item.id === selected)
  const scopeParent = (fields: string[]) => {
    const filter = draft.data_scope.filters.find(item => fields.includes(item.field) && ['eq', 'in'].includes(item.operator))
    return filter ? String(Array.isArray(filter.value) ? filter.value[0] ?? '' : filter.value ?? '') : ''
  }
  const teamDepartment = scopeParent(['department', 'department_id', 'bbak_id'])
  const teamGroup = scopeParent(['group', 'group_id', 'rota_id'])
  const scopeOptions = draft.data_scope.scope_type === 'DEPARTMENT' ? shared.hierarchy.departments : draft.data_scope.scope_type === 'GROUP' ? shared.hierarchy.groups : shared.hierarchy.teams.filter(team => team.department_id === teamDepartment && team.group_id === teamGroup)
  const setScope = (update: Partial<BiScope>) => setDraft({ ...draft, data_scope: { ...draft.data_scope, ...update } })
  const setTeamParent = (field: 'department' | 'group', value: string) => {
    const fields = field === 'department' ? ['department', 'department_id', 'bbak_id', 'group', 'group_id', 'rota_id'] : ['group', 'group_id', 'rota_id']
    setScope({ scope_ids: [], filters: [...draft.data_scope.filters.filter(item => !fields.includes(item.field)), ...(value ? [{ field, operator: 'eq', value }] : [])] })
  }
  const save = async () => { setBusy(true); setError(''); setNotice(''); try { const saved = await biAdminApi.save('user_access', draft, shared.token); setDraft(saved); setBase(pretty(saved)); await shared.onSaved(); setNotice('Права, ролі та область даних користувача збережено.') } catch (reason) { setError(message(reason)) } finally { setBusy(false) } }
  if (!users.length) return <p className="bi-state">Користувачів ще немає. Створіть локальний обліковий запис нижче або виконайте перший вхід через Keycloak.</p>
  return <div className="bia-definition"><div className="bia-list">{users.map(item => <button type="button" className={item.id === selected ? 'active' : ''} disabled={busy || dirty} key={item.id} onClick={() => { const next = createFor(item.id); setSelected(item.id); setDraft(next); setBase(pretty(next)); setError(''); setNotice(''); setInvalid('') }}>{item.display_name || item.username}<small>{item.username} · {item.auth_provider ?? 'local'}</small></button>)}</div><div className="bia-editor"><h3>{user?.display_name || user?.username}</h3><p className="bi-notice">{user?.username} · {user?.id}</p><fieldset disabled={busy} className="bia-form"><Choices title="Ролі користувача" options={(shared.users?.roles ?? []).map(role => ({ key: role.id, title: role.title }))} selected={draft.role_ids} onChange={role_ids => setDraft({ ...draft, role_ids })} /><Choices title="Дозволені функції (checkbox)" options={permissionList(shared).map(key => ({ key, title: key }))} selected={draft.permissions} onChange={permissions => setDraft({ ...draft, permissions })} /><details className="bia-advanced"><summary>Явні заборони (мають пріоритет над ролями)</summary><Choices title="Заборонені права" options={permissionList(shared).map(key => ({ key, title: key }))} selected={draft.denied_permissions} onChange={denied_permissions => setDraft({ ...draft, denied_permissions })} /></details><h4>Data Scope / Область даних</h4><Field label="Тип області"><select value={draft.data_scope.scope_type} onChange={event => setScope({ scope_type: event.target.value as BiScope['scope_type'], scope_ids: [], filters: [] })}>{['NONE', 'ALL', 'DEPARTMENT', 'GROUP', 'TEAM', 'SELF', 'CUSTOM'].map(value => <option key={value}>{value}</option>)}</select></Field>{draft.data_scope.scope_type === "TEAM" && <div className="bia-fields"><Field label="ББАК / відділ для екіпажу"><select value={teamDepartment} onChange={event => setTeamParent("department", event.target.value)}><option value="">Оберіть ББАК</option>{shared.hierarchy.departments.map(item => <option value={item.id} key={item.id}>{item.title}</option>)}</select></Field><Field label="Рота / група для екіпажу"><select value={teamGroup} onChange={event => setTeamParent("group", event.target.value)}><option value="">Оберіть роту</option>{shared.hierarchy.groups.filter(item => item.department_id === teamDepartment).map(item => <option value={item.id} key={item.id}>{item.title}</option>)}</select></Field></div>}{['DEPARTMENT', 'GROUP', 'TEAM'].includes(draft.data_scope.scope_type) && <Choices title={`Область ${draft.data_scope.scope_type}`} options={scopeOptions.map(item => ({ key: item.id, title: `${item.title}${item.department_id ? ` · ${shared.hierarchy.departments.find(department => department.id === item.department_id)?.title ?? item.department_id}` : ''}` }))} selected={draft.data_scope.scope_ids} onChange={scope_ids => setScope({ scope_ids })} />}{draft.data_scope.scope_type === 'CUSTOM' && <FiltersEditor title="Обмежувальні фільтри області" filters={draft.data_scope.filters} metadata={shared.metadata} onChange={filters => setScope({ filters })} onError={setInvalid} />}{draft.data_scope.scope_type === 'NONE' && <p className="bi-notice">NONE: дані закриті до призначення області.</p>}{draft.data_scope.scope_type === 'SELF' && <p className="bi-notice">SELF потребує підтвердженого поля власника запису. Поточний ClickHouse dataset такого поля не містить: ця область повертає порожні дані до налаштування owner mapping на сервері.</p>}<Field label="Точність restricted comparison"><select value={draft.comparison_precision} onChange={event => setDraft({ ...draft, comparison_precision: event.target.value })}>{['EXACT', 'ROUND_1', 'ROUND_5', 'RANGE'].map(value => <option key={value}>{value}</option>)}</select></Field></fieldset>{error && <div className="bi-error-banner" role="alert">{error}</div>}{notice && <p className="bi-notice" role="status">{notice}</p>}<div className="bia-actions"><button className="secondary" type="button" disabled={busy || Boolean(invalid)} onClick={() => void save()}><Save size={14} /> Зберегти доступ</button>{dirty && <button className="secondary" type="button" disabled={busy} onClick={() => { setDraft(JSON.parse(base) as BiUserAccess); setInvalid('') }}>Скасувати</button>}</div></div></div>
}

export function AnalyticsAdministrationSection({ section, token, onDirty }: { section: AnalyticsAdministrationSectionId; token?: string; onDirty: (value: boolean) => void }) {
  const queryClient = useQueryClient()
  const [dirty, setDirty] = useState(false)
  const needs = {
    dashboards: section === 'comparison', metrics: section === 'metrics', kpis: section === 'kpis',
    catalog: section === 'comparison' || section === 'policies',
    weightSets: section === 'metrics' || section === 'weights' || section === 'weight_sets', weights: section === 'weights',
    hierarchy: section === 'comparison' || section === 'users', users: section === 'comparison' || section === 'users' || section === 'roles',
  }
  const dashboards = useQuery({ queryKey: ['bi-admin', 'dashboards', token], queryFn: ({ signal }) => biAdminApi.list<DashboardDefinition>('dashboards', token, signal), enabled: needs.dashboards })
  const metrics = useQuery({ queryKey: ['bi-admin', 'metrics', token], queryFn: ({ signal }) => biAdminApi.list<BiMetric>('metrics', token, signal), enabled: needs.metrics })
  const kpis = useQuery({ queryKey: ['bi-admin', 'kpis', token], queryFn: ({ signal }) => biAdminApi.list<BiKpi>('kpis', token, signal), enabled: needs.kpis })
  const catalog = useQuery({ queryKey: ['bi-admin', 'catalog', token], queryFn: ({ signal }) => biAdminApi.catalog(token, signal), enabled: needs.catalog })
  const weightSets = useQuery({ queryKey: ['bi-admin', 'weight_sets', token], queryFn: ({ signal }) => biAdminApi.list<BiWeightSet>('weight_sets', token, signal), enabled: needs.weightSets })
  const weights = useQuery({ queryKey: ['bi-admin', 'category_weights', token], queryFn: ({ signal }) => biAdminApi.list<BiWeight>('category_weights', token, signal), enabled: needs.weights })
  const metadata = useQuery({ queryKey: ['bi-admin', 'metadata', token], queryFn: ({ signal }) => biAdminApi.metadata(token, signal) })
  const hierarchy = useQuery({ queryKey: ['bi-admin', 'hierarchy', token], queryFn: ({ signal }) => biAdminApi.hierarchy(token, signal), enabled: needs.hierarchy })
  const users = useQuery({ queryKey: ['bi-admin', 'users', token], queryFn: ({ signal }) => biAdminApi.users(token, signal), enabled: needs.users })
  const queries = [metadata, ...(needs.dashboards ? [dashboards] : []), ...(needs.metrics ? [metrics] : []), ...(needs.kpis ? [kpis] : []), ...(needs.catalog ? [catalog] : []), ...(needs.weightSets ? [weightSets] : []), ...(needs.weights ? [weights] : []), ...(needs.users ? [users] : [])]
  const refresh = async () => { await queryClient.invalidateQueries({ queryKey: ['bi-admin'] }); await Promise.all([queryClient.invalidateQueries({ queryKey: ['bi-dashboards'] }), queryClient.invalidateQueries({ queryKey: ['bi-dashboard'] }), queryClient.invalidateQueries({ queryKey: ['bi-metadata'] }), queryClient.invalidateQueries({ queryKey: ['bi-hierarchy'] }), queryClient.invalidateQueries({ queryKey: ['bi-dashboard-query'] }), queryClient.invalidateQueries({ queryKey: ['integrated-query'] }), queryClient.invalidateQueries({ queryKey: ['analytics-catalog'] }), queryClient.invalidateQueries({ queryKey: ['integrated-definition'] })]) }
  useEffect(() => { void queryClient.invalidateQueries({ queryKey: ['bi-admin'] }) }, [token])
  useEffect(() => { if (!dirty) return; const prevent = (event: BeforeUnloadEvent) => { event.preventDefault() }; window.addEventListener('beforeunload', prevent); return () => window.removeEventListener('beforeunload', prevent) }, [dirty])
  const canManageCache = metadata.data?.permissions?.some(permission => permission === '*' || permission === 'analytics.cache.manage')
  useEffect(() => { onDirty(dirty); return () => onDirty(false) }, [dirty, onDirty])
  const loading = queries.some(query => query.isPending)
  const error = queries.find(query => query.isError)?.error
  const shared = useMemo<Shared | null>(() => metadata.data ? { catalog: needs.catalog ? catalog.data : undefined, weightSets: needs.weightSets ? weightSets.data : undefined, metadata: metadata.data, hierarchy: needs.hierarchy && hierarchy.data ? hierarchy.data : { departments: [], groups: [], teams: [] }, users: needs.users && users.data ? users.data : { users: [], access: [], roles: [], permissions: [] }, token, onSaved: refresh, onDirty: setDirty } : null, [catalog.data, weightSets.data, metadata.data, hierarchy.data, users.data, token, section])
  const cacheKpis = useMemo(() => (metadata.data?.metrics ?? []).filter(metric => metric.kind === 'kpi').map(metric => ({ ...defaultKpi(), id: metric.id ?? metric.key, key: metric.key, title: metric.title })), [metadata.data])
  const selected = analyticsAdministrationSections.find(item => item.key === section)!
  return <section className="bia-section" aria-label={selected.title}>
    <header className="bia-heading"><div><h3>{selected.title}</h3><p>{selected.description}</p></div><button type="button" className="secondary" disabled={loading || dirty} onClick={() => void refresh()}><RefreshCw size={14} /> Оновити</button></header>
    {needs.hierarchy && hierarchy.isError && <p className="bi-notice" role="status">Організаційний довідник недоступний: {hierarchy.error.message}. Призначення областей даних потребує підключеного джерела.</p>}
    {loading ? <p className="bi-state" role="status">Завантаження налаштувань…</p> : error ? <div className="bi-error-banner" role="alert">{error.message}</div> : shared && <div>
      {section === 'comparison' && <ComparisonPresetsEditor items={(dashboards.data ?? []).filter(item => item.type === 'COMPARISON')} shared={shared} />}
      {section === 'metrics' && <MetricEditor items={metrics.data ?? []} shared={shared} />}
      {section === 'kpis' && <KpiEditor items={kpis.data ?? []} shared={shared} />}
      {section === 'weight_sets' && <WeightSetEditor items={weightSets.data ?? []} shared={shared} />}
      {section === 'policies' && <KpiPolicyAdministration token={token} catalog={catalog.data} onDirty={setDirty} />}
      {section === 'weights' && <WeightEditor items={weights.data ?? []} shared={shared} />}
      {section === 'users' && <UsersEditor shared={shared} />}
      {section === 'roles' && <RoleEditor items={users.data?.roles ?? []} shared={shared} />}
      {section === 'cache' && (canManageCache ? <CacheAdministration token={token} metrics={metadata.data?.metrics ?? []} kpis={cacheKpis} /> : <p className="bi-notice">Недостатньо прав для керування кешем.</p>)}
    </div>}
  </section>
}
